    {
      "rank": 1,
      "ballot_id": "B033",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED established a powerful regime for coupling superconducting artificial atoms to microwave photons, enabling precise tests of light–matter interaction and underpinning a major platform for quantum information.",
        "attribution": "Blais developed the theoretical framework, while Wallraff and Schoelkopf were central to experimental realization and development. The field is broad, so a prize would need to recognize foundational contributions rather than the entire subsequent platform.",
        "maturity": "The phenomena and core architecture have been reproduced and extended across laboratories over many years.",
        "uncertainties": [
          "The boundary between foundational circuit-QED physics and later quantum-computing engineering is not sharp."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions made quantum logic and controlled many-body simulation experimentally concrete, connecting foundational proposals to exceptionally precise quantum control.",
        "attribution": "Cirac and Zoller supplied influential theory and architectures; Blatt led landmark experimental demonstrations. The proposed trio captures the close theory–experiment relationship.",
        "maturity": "The platform has a long record of independent replication, increasingly capable processors, and controlled simulation experiments.",
        "uncertainties": [
          "The field's many subsequent advances make it difficult to define a compact prize scope around its earliest achievements."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum spin Hall effect and topological insulators revealed a new class of electronic states protected by topology, with broad consequences for condensed-matter physics.",
        "attribution": "Kane and Mele developed the key theoretical framework; Molenkamp's experiments established the quantum spin Hall state in HgTe quantum wells. This is a strong theory–experiment attribution.",
        "maturity": "The initial effects are well established, though materials and applications continue to evolve.",
        "uncertainties": [
          "The proposed credit centers on the quantum spin Hall foundation; the wider topological-insulator field includes important contributions not represented here."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and opened a regime where clock comparisons test fundamental physics as well as improve measurement.",
        "attribution": "Katori introduced the lattice-clock concept and its key operating principle; Ye made major experimental advances in precision and clock performance. The two contributions are complementary.",
        "maturity": "Performance has advanced over many years, with independent realizations and broad metrological use.",
        "uncertainties": [
          "A committee would need to distinguish the foundational clock concept from a large international effort that refined it."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Markus Aspelmeyer",
        "Oskar Painter",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics created a versatile means to control mechanical motion with light and probe quantum behavior in massive systems, a substantial advance in quantum optics.",
        "attribution": "The credited researchers made complementary theoretical and experimental contributions to cavity optomechanics and its development. The broad field makes precise allocation among early contributions challenging.",
        "maturity": "Core effects and control methods are well established across experiments, while tests of quantum behavior at larger scales remain an active frontier.",
        "uncertainties": [
          "The most fundamental quantum-regime claims and their implications for macroscopic systems remain under active development."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade and programmable neutral-atom arrays enable highly controllable many-body systems and quantum information experiments, with strong potential for foundational discoveries.",
        "attribution": "Browaeys, Saffman, and Lukin represent key experimental and conceptual strands in blockade and array control. The credited set omits other important contributors to the wider platform.",
        "maturity": "The platform has advanced rapidly and achieved impressive control, but its scientific legacy and long-term robustness are still being established.",
        "uncertainties": [
          "The balance between a fundamental physics achievement and an emerging quantum-technology platform is not yet settled."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B008",
      "proposed_laureates": [
        "David D. Awschalom",
        "Jörg Wrachtrup",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Optical control of solid-state defect spins brought coherent quantum control and nanoscale sensing into a practical material system, creating important tools for quantum science.",
        "attribution": "Awschalom, Wrachtrup, and Lukin made central contributions to defect-spin control and its physics. Walsworth's work is especially associated with sensing; selecting a limited group necessarily narrows the scope.",
        "maturity": "Coherent control and sensing have been demonstrated widely, while performance and applications continue to improve.",
        "uncertainties": [
          "The proposed discovery combines several related advances, making the prize boundary and division of credit difficult."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Alan H. Guth",
        "Andrei Linde",
        "Viatcheslav Mukhanov"
      ],
      "assessment": {
        "nobel_worthiness": "Inflation offers a compelling account of the early universe and links quantum fluctuations to cosmic structure, with profound conceptual reach.",
        "attribution": "Guth and Linde developed influential inflationary frameworks; Mukhanov made foundational contributions to the theory of primordial perturbations. Credit across the development is extensive.",
        "maturity": "Several broad predictions accord with cosmological observations, but the inflationary mechanism and its distinctive signatures remain unconfirmed.",
        "uncertainties": [
          "No unique inflationary model has been established, and a decisive detection of primordial gravitational waves is lacking.",
          "Theoretical and observational contributions beyond the proposed names are substantial."
        ]
      }
    }
  ]
}
